import math
import sys
# Increase recursion limit to handle depth 50 reliably
sys.setrecursionlimit(3000)

F = 163
MAX_TURNS = 50
N_LIMIT = 500 

def get_valid_moves(N):
    """Returns a set of valid moves X (divisor or multiple of N, X > 1) 
    that lead to states within a practical search limit."""
    moves = set()

    # 1. Divisors of N
    for i in range(2, int(math.sqrt(N)) + 1):
        if N % i == 0:
            moves.add(i)
            moves.add(N // i)
    moves.add(N) # N is a divisor of itself

    # 2. Multiples of N
    k = 2
    while True:
        multiple = k * N

        # Crucial Pruning: Limit search space
        if multiple > N_LIMIT and N > 1:
             break

        moves.add(multiple)
        k += 1

    return sorted(list(moves))

def calculate_guaranteed_shortest_path(N_start, F_target, max_turns, N_limit):
    """
    Calculates the guaranteed shortest path length from N_start to F_target using minimax.
    Returns float('inf') if unreachable within practical limits.
    """
    memo = {}

    def R(N):
        if N == F_target:
            return 0

        # Safety checks and bounds
        if N < 2 and N != F_target: 
            return float('inf')
        if N > N_limit and N > F_target + max_turns * 2: 
            return float('inf')

        if N in memo:
            return memo[N]

        moves = get_valid_moves(N)

        if not moves:
            memo[N] = float('inf')
            return float('inf')

        min_max_R = float('inf')

        for X in moves:
            # Opponent chooses max(R(X-1), R(X+1))
            r_minus = R(X - 1)
            r_plus = R(X + 1)

            worst_case_R = max(r_minus, r_plus)

            # Only consider moves leading to a finite worst-case outcome
            if worst_case_R != float('inf'):
                min_max_R = min(min_max_R, 1 + worst_case_R)

        memo[N] = min_max_R
        return min_max_R

    return R(N_start)

# Test cases
S_values = [2, 3, 7, 13]
results = {}

print(f"--- Starting Minimax Search for F={F} (Max Turns={MAX_TURNS}) with N_LIMIT={N_LIMIT} ---")

for S in S_values:
    print(f"Searching for S = {S}...")
    try:
        path_length = calculate_guaranteed_shortest_path(S, F, MAX_TURNS, N_LIMIT)
        results[S] = path_length
        status = "SUCCESS" if path_length <= MAX_TURNS else "FAILURE (Too Long)"
        print(f"Found guaranteed shortest path length for S={S}: {path_length} ({status})")
